-- =============================================================================
-- HireOrbit AI — consolidated database schema
--
-- Single-file alternative to applying every database/*.sql migration by hand.
-- Every block below is the verbatim content of its source file; this file is
-- mechanically generated by scripts/build-init-sql.mjs. To regenerate after
-- editing any individual source file:
--
--   node scripts/build-init-sql.mjs
--
-- Apply to a fresh database:
--
--   createdb hireorbitai
--   psql -d hireorbitai -c 'CREATE EXTENSION IF NOT EXISTS pgcrypto'
--   psql -d hireorbitai -f database/init.sql
--
-- The file is idempotent — re-running on an existing database is safe. Every
-- table uses CREATE TABLE IF NOT EXISTS, every enum is wrapped in a
-- duplicate_object guard, every column add uses ALTER TABLE ... ADD COLUMN
-- IF NOT EXISTS, every index uses CREATE INDEX IF NOT EXISTS.
--
-- For new schema changes AFTER this baseline, use the migration runner under
-- backend/migrations/ — DON'T edit this file directly for new tables.
-- =============================================================================



-- ###########################################################################
-- # Foundation — base schema
-- ###########################################################################


-- --- schema.sql -----------------------------------------------------------

-- HireOrbit AI — Database Schema
-- PostgreSQL (self-hosted on the VPS)
-- Run via `psql` against the application database, e.g.
--   psql "$DATABASE_URL" -f database/schema.sql

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- ENUMS
-- ---------------------------------------------------------------------------
do $$ begin
  create type user_role as enum ('SUPER_ADMIN', 'MANAGER', 'RECRUITER', 'CONSULTANT');
exception when duplicate_object then null; end $$;

do $$ begin
  create type invitation_status as enum ('PENDING', 'ACCEPTED', 'EXPIRED', 'REVOKED');
exception when duplicate_object then null; end $$;

do $$ begin
  create type consultant_marketing_status as enum ('ACTIVE', 'PAUSED', 'PLACED');
exception when duplicate_object then null; end $$;

do $$ begin
  create type application_status as enum ('SUBMITTED', 'SCREENING', 'INTERVIEW', 'OFFER', 'REJECTED', 'WITHDRAWN');
exception when duplicate_object then null; end $$;

do $$ begin
  create type interview_type as enum ('PHONE', 'TECHNICAL', 'BEHAVIORAL', 'ONSITE', 'FINAL', 'MOCK');
exception when duplicate_object then null; end $$;

do $$ begin
  create type interview_status as enum ('SCHEDULED', 'COMPLETED', 'CANCELLED', 'NO_SHOW');
exception when duplicate_object then null; end $$;

do $$ begin
  create type reminder_status as enum ('PENDING', 'SENT', 'DONE', 'SNOOZED');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- USERS
-- Canonical user table. Owns the password hash and the session-version
-- counter that lets us revoke all access tokens for a user with one UPDATE.
-- ---------------------------------------------------------------------------
create table if not exists public.users (
  id uuid primary key default gen_random_uuid(),
  email text unique not null,
  password_hash text,
  full_name text,
  phone text,
  role user_role not null default 'CONSULTANT',
  avatar_url text,
  is_active boolean not null default true,
  session_version integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on column public.users.password_hash is
  'bcrypt hash of the user''s password. Null only during the brief window between createUser and the welcome email being sent.';
comment on column public.users.session_version is
  'Monotonic counter bumped on global sign-out / password change. JWTs embed the version at issue time; mismatch on /auth/me forces re-login.';

-- ---------------------------------------------------------------------------
-- AUTH SESSIONS
-- Refresh-token store. We keep bcrypt hashes (never the raw secret) so a DB
-- leak doesn''t hand the attacker a usable refresh credential.
-- ---------------------------------------------------------------------------
create table if not exists public.auth_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(id) on delete cascade,
  refresh_hash text not null,
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  user_agent text,
  ip_address text
);
create index if not exists auth_sessions_user_id_idx on public.auth_sessions (user_id);
create index if not exists auth_sessions_expires_idx on public.auth_sessions (expires_at);

-- ---------------------------------------------------------------------------
-- RECRUITERS
-- ---------------------------------------------------------------------------
create table if not exists public.recruiters (
  id uuid primary key default gen_random_uuid(),
  user_id uuid unique not null references public.users(id) on delete cascade,
  manager_id uuid references public.users(id) on delete set null,
  team text,
  target_submissions_per_week int default 10,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- CONSULTANTS
-- ---------------------------------------------------------------------------
create table if not exists public.consultants (
  id uuid primary key default gen_random_uuid(),
  user_id uuid unique not null references public.users(id) on delete cascade,
  recruiter_id uuid references public.recruiters(id) on delete set null,
  visa_status text,
  current_location text,
  preferred_locations text[],
  primary_skill text,
  total_experience_years numeric(4,1),
  relocation boolean default false,
  remote_only boolean default false,
  expected_rate numeric(10,2),
  marketing_status consultant_marketing_status not null default 'ACTIVE',
  linkedin_url text,
  github_url text,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- INVITATIONS
-- ---------------------------------------------------------------------------
create table if not exists public.invitations (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  role user_role not null,
  token text unique not null,
  invited_by uuid references public.users(id) on delete set null,
  status invitation_status not null default 'PENDING',
  expires_at timestamptz not null,
  accepted_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists invitations_email_idx on public.invitations (email);
create index if not exists invitations_status_idx on public.invitations (status);

-- ---------------------------------------------------------------------------
-- RESUMES — version history per consultant
-- ---------------------------------------------------------------------------
create table if not exists public.resumes (
  id uuid primary key default gen_random_uuid(),
  consultant_id uuid not null references public.consultants(id) on delete cascade,
  version int not null,
  file_name text not null,
  storage_path text not null,           -- storage object path
  mime_type text,
  size_bytes bigint,
  ai_score numeric(5,2),                -- 0-100
  ai_feedback jsonb,
  is_current boolean not null default false,
  uploaded_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (consultant_id, version)
);
create index if not exists resumes_consultant_idx on public.resumes (consultant_id);
create unique index if not exists resumes_one_current_per_consultant
  on public.resumes (consultant_id) where is_current;

-- ---------------------------------------------------------------------------
-- VENDORS
-- ---------------------------------------------------------------------------
create table if not exists public.vendors (
  id uuid primary key default gen_random_uuid(),
  company_name text not null,
  contact_name text,
  contact_email text,
  contact_phone text,
  website text,
  tier text,                        -- e.g. T1/T2/Prime
  tags text[],
  notes text,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists vendors_company_idx on public.vendors (company_name);

-- ---------------------------------------------------------------------------
-- CLIENTS
-- ---------------------------------------------------------------------------
create table if not exists public.clients (
  id uuid primary key default gen_random_uuid(),
  company_name text not null,
  industry text,
  contact_name text,
  contact_email text,
  contact_phone text,
  location text,
  notes text,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists clients_company_idx on public.clients (company_name);

-- ---------------------------------------------------------------------------
-- JOBS
-- ---------------------------------------------------------------------------
create table if not exists public.jobs (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  client_id uuid references public.clients(id) on delete set null,
  vendor_id uuid references public.vendors(id) on delete set null,
  location text,
  remote boolean default false,
  job_type text,                        -- W2/C2C/1099/FTE
  rate_min numeric(10,2),
  rate_max numeric(10,2),
  description text,
  required_skills text[],
  source_url text,
  posted_at timestamptz,
  closes_at timestamptz,
  is_active boolean not null default true,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists jobs_title_idx on public.jobs (title);
create index if not exists jobs_active_idx on public.jobs (is_active);

-- ---------------------------------------------------------------------------
-- APPLICATIONS — consultant ↔ job submissions
-- ---------------------------------------------------------------------------
create table if not exists public.applications (
  id uuid primary key default gen_random_uuid(),
  consultant_id uuid not null references public.consultants(id) on delete cascade,
  job_id uuid not null references public.jobs(id) on delete cascade,
  resume_id uuid references public.resumes(id) on delete set null,
  vendor_id uuid references public.vendors(id) on delete set null,
  recruiter_id uuid references public.recruiters(id) on delete set null,
  ats_score numeric(5,2),
  ats_feedback jsonb,
  status application_status not null default 'SUBMITTED',
  submitted_at timestamptz not null default now(),
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists applications_consultant_idx on public.applications (consultant_id);
create index if not exists applications_job_idx on public.applications (job_id);
-- Duplicate-submission guard: same consultant + same job + same vendor
create unique index if not exists applications_duplicate_guard
  on public.applications (consultant_id, job_id, vendor_id);

-- ---------------------------------------------------------------------------
-- INTERVIEWS
-- ---------------------------------------------------------------------------
create table if not exists public.interviews (
  id uuid primary key default gen_random_uuid(),
  application_id uuid references public.applications(id) on delete cascade,
  consultant_id uuid not null references public.consultants(id) on delete cascade,
  type interview_type not null,
  scheduled_at timestamptz not null,
  duration_minutes int default 60,
  interviewer text,
  meeting_url text,
  status interview_status not null default 'SCHEDULED',
  is_mock boolean not null default false,
  feedback jsonb,                       -- {strengths, weaknesses, rating, notes}
  feedback_submitted_at timestamptz,
  feedback_submitted_by uuid references public.users(id) on delete set null,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists interviews_consultant_idx on public.interviews (consultant_id);
create index if not exists interviews_scheduled_idx on public.interviews (scheduled_at);

-- ---------------------------------------------------------------------------
-- REMINDERS — follow-ups
-- ---------------------------------------------------------------------------
create table if not exists public.reminders (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.users(id) on delete cascade,
  title text not null,
  description text,
  related_type text,                    -- 'application' | 'interview' | 'vendor' | ...
  related_id uuid,
  due_at timestamptz not null,
  status reminder_status not null default 'PENDING',
  sent_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists reminders_owner_due_idx on public.reminders (owner_id, due_at);

-- ---------------------------------------------------------------------------
-- RECRUITER DAILY ACTIVITY — denormalized daily report
-- ---------------------------------------------------------------------------
create table if not exists public.recruiter_daily_activity (
  id uuid primary key default gen_random_uuid(),
  recruiter_id uuid not null references public.recruiters(id) on delete cascade,
  activity_date date not null,
  submissions_count int not null default 0,
  interviews_scheduled int not null default 0,
  interviews_completed int not null default 0,
  vendor_calls int not null default 0,
  offers int not null default 0,
  placements int not null default 0,
  notes text,
  created_at timestamptz not null default now(),
  unique (recruiter_id, activity_date)
);
create index if not exists rda_recruiter_date_idx
  on public.recruiter_daily_activity (recruiter_id, activity_date desc);

-- ---------------------------------------------------------------------------
-- updated_at trigger
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

do $$ declare t text;
begin
  for t in select unnest(array[
    'users','recruiters','consultants','vendors','clients','jobs',
    'applications','interviews'
  ]) loop
    execute format('drop trigger if exists trg_%s_updated_at on public.%s', t, t);
    execute format('create trigger trg_%s_updated_at before update on public.%s
                    for each row execute function public.set_updated_at()', t, t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Access control
--
-- The backend is the single client of this database. All authorization
-- happens in the Express layer (middleware/auth.ts + per-route guards), so
-- we deliberately leave RLS disabled — the API enforces who can read what.
--
-- If you ever expose this database directly to a non-server consumer, you
-- MUST re-enable RLS and write role-aware policies before doing so.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- TASKS module (see also database/tasks.sql)
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- ENUMS
-- ---------------------------------------------------------------------------
do $$ begin
  create type task_status as enum
    ('BACKLOG', 'TODO', 'IN_PROGRESS', 'BLOCKED', 'REVIEW', 'COMPLETED', 'CANCELLED');
exception when duplicate_object then null; end $$;

do $$ begin
  create type task_priority as enum ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- TASKS
-- ---------------------------------------------------------------------------
create table if not exists public.tasks (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  status task_status not null default 'BACKLOG',
  priority task_priority not null default 'MEDIUM',
  assignee_id uuid references public.users(id) on delete set null,
  created_by uuid references public.users(id) on delete set null,
  related_consultant_id uuid references public.consultants(id) on delete set null,
  related_recruiter_id uuid references public.recruiters(id) on delete set null,
  due_at timestamptz,
  completed_at timestamptz,
  order_index int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists tasks_assignee_idx on public.tasks (assignee_id);
create index if not exists tasks_status_idx on public.tasks (status);
create index if not exists tasks_due_idx on public.tasks (due_at);
create index if not exists tasks_created_by_idx on public.tasks (created_by);

-- ---------------------------------------------------------------------------
-- TASK COMMENTS
-- ---------------------------------------------------------------------------
create table if not exists public.task_comments (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks(id) on delete cascade,
  author_id uuid references public.users(id) on delete set null,
  body text not null,
  created_at timestamptz not null default now()
);
create index if not exists task_comments_task_idx on public.task_comments (task_id, created_at);

-- ---------------------------------------------------------------------------
-- TASK ATTACHMENTS
-- ---------------------------------------------------------------------------
create table if not exists public.task_attachments (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks(id) on delete cascade,
  uploaded_by uuid references public.users(id) on delete set null,
  file_name text not null,
  storage_path text not null,
  mime_type text,
  size_bytes bigint,
  created_at timestamptz not null default now()
);
create index if not exists task_attachments_task_idx on public.task_attachments (task_id);

-- ---------------------------------------------------------------------------
-- updated_at trigger for tasks
-- ---------------------------------------------------------------------------
do $$ begin
  drop trigger if exists trg_tasks_updated_at on public.tasks;
  create trigger trg_tasks_updated_at before update on public.tasks
    for each row execute function public.set_updated_at();
end $$;

-- ---------------------------------------------------------------------------
-- Row Level Security (backend uses service-role key and bypasses these).
-- ---------------------------------------------------------------------------
alter table public.tasks enable row level security;
alter table public.task_comments enable row level security;
alter table public.task_attachments enable row level security;


-- ###########################################################################
-- # Identity + auth — extends public.users
-- ###########################################################################


-- --- auth-hardening.sql ---------------------------------------------------

-- =============================================================================
-- Auth hardening migration
--
-- Adds the columns + tables required by the enterprise auth flow:
--   - first-login forced password change
--   - custom (Brevo-backed) forgot-password flow
--   - auth audit trail
--   - account lockout after failed logins
-- Idempotent: safe to re-run.
-- =============================================================================

-- --- public.users additions --------------------------------------------------
alter table public.users
  add column if not exists must_change_password           boolean      default true,
  add column if not exists temporary_password_sent_at     timestamptz,
  add column if not exists last_password_changed_at       timestamptz,
  add column if not exists password_expires_at            timestamptz,
  add column if not exists failed_login_attempts          integer      default 0,
  add column if not exists locked_until                   timestamptz;

comment on column public.users.must_change_password is
  'True if the user signed in with a temp password and has not yet rotated it. Blocks all routes until cleared.';
comment on column public.users.temporary_password_sent_at is
  'When the most recent temporary password was issued. Combined with the 24h expiry check at login.';
comment on column public.users.password_expires_at is
  'Optional hard expiry for the current password. Null = no expiry.';

-- --- password_reset_tokens ---------------------------------------------------
-- Stores hashed reset tokens. The raw token is only ever known to the user
-- (delivered in the Brevo email). We index by user_id so cleanup is cheap.
create table if not exists public.password_reset_tokens (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references public.users(id) on delete cascade,
  token_hash  text not null,
  expires_at  timestamptz not null,
  used_at     timestamptz,
  ip_address  text,
  created_at  timestamptz default now()
);

create index if not exists password_reset_tokens_user_id_idx
  on public.password_reset_tokens (user_id);

-- A single-column index on token_hash gives us O(log n) lookup at validation
-- time. Unique constraint guards against accidental duplicate inserts.
create unique index if not exists password_reset_tokens_token_hash_uidx
  on public.password_reset_tokens (token_hash);

-- --- auth_audit_logs ---------------------------------------------------------
-- One row per security-relevant event. Append-only. Frontend never queries
-- this directly — only ops via the audit UI / Grafana.
create table if not exists public.auth_audit_logs (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid,
  email       text,
  action      text not null,
  -- e.g. 'login_success', 'login_failed', 'logout',
  --      'password_changed', 'password_reset_requested', 'password_reset_completed',
  --      'account_locked', 'admin_created_user', 'must_change_password_enforced'
  ip_address  text,
  user_agent  text,
  metadata    jsonb,
  created_at  timestamptz default now()
);

create index if not exists auth_audit_logs_user_id_created_idx
  on public.auth_audit_logs (user_id, created_at desc);

create index if not exists auth_audit_logs_action_created_idx
  on public.auth_audit_logs (action, created_at desc);

-- --- Cleanup function: expired reset tokens ----------------------------------
-- Schedule via pg_cron or your existing job runner; or call manually:
--   select public.purge_expired_password_reset_tokens();
create or replace function public.purge_expired_password_reset_tokens()
returns integer
language plpgsql
as $$
declare
  deleted integer;
begin
  delete from public.password_reset_tokens
   where expires_at < now() - interval '7 days'
      or used_at is not null and used_at < now() - interval '7 days';
  get diagnostics deleted = row_count;
  return deleted;
end;
$$;

-- --- Access control ----------------------------------------------------------
-- After the migration off PostgREST, the backend owns every query against
-- these tables. We leave RLS disabled — the API enforces who can read what.
-- If the database is ever exposed directly to clients, re-enable RLS and add
-- the appropriate role-based policies before doing so.


-- --- admin-user-management.sql --------------------------------------------

-- =============================================================================
-- Admin user-management migration
--
-- Adds the columns + enum the admin "All Users" surface needs:
--   - status: 5-state enum (active / inactive / suspended / pending_verification / banned)
--   - status_reason / status_changed_at / status_changed_by: who/when/why
--   - last_login_at: filled on every successful sign-in
--   - notes: free-text admin notes ("VIP client", "spam recruiter", etc.)
--
-- Auth middleware reads `status` and refuses any non-`active` value, so
-- changing the status is sufficient to lock a user out — refresh tokens are
-- additionally revoked at the API layer (see auth.service.ts).
--
-- Idempotent: safe to re-run.
-- =============================================================================

-- 1. Status enum -------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_type where typname = 'user_status') then
    create type user_status as enum (
      'active',
      'inactive',
      'suspended',
      'pending_verification',
      'banned'
    );
  end if;
end $$;

-- 2. Add the new columns ------------------------------------------------------
alter table public.users
  add column if not exists status              user_status not null default 'active',
  add column if not exists status_reason       text,
  add column if not exists status_changed_at   timestamptz,
  add column if not exists status_changed_by   uuid references public.users(id) on delete set null,
  add column if not exists last_login_at       timestamptz,
  add column if not exists admin_notes         text;

comment on column public.users.status is
  '5-state account status. Auth middleware refuses any non-`active` value.';
comment on column public.users.status_reason is
  'Free-text reason set by the admin when status moves away from active.';
comment on column public.users.status_changed_by is
  'public.users.id of the admin who last changed the status.';
comment on column public.users.last_login_at is
  'Stamped on every successful sign-in by /auth/login.';
comment on column public.users.admin_notes is
  'Internal admin notes — never exposed to non-admins.';

-- 3. Backfill: existing is_active → status -----------------------------------
-- If the legacy is_active column exists and is false, mark them inactive.
do $$
begin
  if exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'users' and column_name = 'is_active'
  ) then
    update public.users
       set status = 'inactive'
     where is_active = false
       and status = 'active';
  end if;
end $$;

-- 4. Indexes for admin filtering ---------------------------------------------
create index if not exists users_status_idx          on public.users (status);
create index if not exists users_role_status_idx     on public.users (role, status);
create index if not exists users_last_login_at_idx   on public.users (last_login_at desc nulls last);

-- 5. Audit log additions -----------------------------------------------------
-- The auth_audit_logs.action column is just `text`, so we don't need a schema
-- change. The new actions the admin surface will write are:
--   admin_user_status_changed
--   admin_user_password_reset
--   admin_user_deactivated     (status -> inactive/suspended/banned)
--   admin_user_reactivated     (status -> active)
--   admin_user_deleted         (hard delete via db.auth.admin.deleteUser)
--   admin_user_impersonated    (future)


-- --- user-profile-fields.sql ----------------------------------------------

-- HireOrbit AI — extended user profile fields.
--
-- Adds first/last name and address fields on the shared users table so that
-- recruiters, managers, and directors can view full contact details for any
-- user (recruiter, consultant, manager, director) in a single profile page.
--
-- Idempotent: safe to re-run.

alter table public.users
  add column if not exists first_name     text,
  add column if not exists last_name      text,
  add column if not exists address_line1  text,
  add column if not exists address_line2  text,
  add column if not exists city           text,
  add column if not exists state          text,
  add column if not exists postal_code    text,
  add column if not exists country        text,
  add column if not exists timezone       text,
  add column if not exists linkedin_url   text;

-- Best-effort backfill: split existing full_name into first/last parts when
-- first_name is null. Safe to re-run — only touches rows still missing data.
update public.users
   set first_name = trim(split_part(full_name, ' ', 1)),
       last_name  = case
                      when position(' ' in full_name) > 0
                        then trim(substring(full_name from position(' ' in full_name) + 1))
                      else null
                    end
 where full_name is not null
   and first_name is null;

notify pgrst, 'reload schema';


-- --- roles-developer-hr.sql -----------------------------------------------

-- HireOrbit AI — adds DEVELOPER + HR_MANAGER to the user_role enum.
-- Both are manager-tier internally: full org visibility + can manage day-to-day
-- operations, but NOT feature flags or other owner-only actions.
-- Idempotent: safe to re-run.

alter type user_role add value if not exists 'DEVELOPER';
alter type user_role add value if not exists 'HR_MANAGER';


-- --- roles-hierarchy.sql --------------------------------------------------

-- HireOrbit AI — extended role hierarchy
-- Adds CEO / CTO / DIRECTOR to the user_role enum + a generic reports_to
-- pointer on users so org chains beyond the recruiter→manager link are
-- representable.
-- Idempotent: safe to re-run.

-- ALTER TYPE ... ADD VALUE IF NOT EXISTS works on Postgres 9.6+.
alter type user_role add value if not exists 'CEO';
alter type user_role add value if not exists 'CTO';
alter type user_role add value if not exists 'DIRECTOR';

-- Generic "reports to" so the leadership chain can be modeled without bolting
-- onto recruiters.manager_id. Self-referential.
alter table public.users add column if not exists reports_to uuid
  references public.users(id) on delete set null;
create index if not exists users_reports_to_idx on public.users (reports_to);


-- --- recruiter-managers.sql -----------------------------------------------

-- HireOrbit AI — many-to-many recruiter ↔ manager / director assignment
-- A recruiter can now report into multiple managers / directors at once.
-- Backfills from the existing single-manager column on recruiters.
-- Idempotent: safe to re-run.

create table if not exists public.recruiter_managers (
  recruiter_id uuid not null references public.recruiters(id) on delete cascade,
  manager_id uuid not null references public.users(id) on delete cascade,
  -- "primary" — used by reports/dashboards when a single "lead" is needed.
  -- The first row inserted for a recruiter is marked primary automatically.
  is_primary boolean not null default false,
  assigned_by uuid references public.users(id) on delete set null,
  assigned_at timestamptz not null default now(),
  primary key (recruiter_id, manager_id)
);

create index if not exists recruiter_managers_recruiter_idx
  on public.recruiter_managers (recruiter_id);
create index if not exists recruiter_managers_manager_idx
  on public.recruiter_managers (manager_id);

-- Only one primary per recruiter.
create unique index if not exists recruiter_managers_one_primary_per_recruiter
  on public.recruiter_managers (recruiter_id) where is_primary;

alter table public.recruiter_managers enable row level security;

-- Backfill: if a recruiter already has a manager_id, mirror it into the new
-- table as the primary assignment.
insert into public.recruiter_managers (recruiter_id, manager_id, is_primary)
select id, manager_id, true
from public.recruiters
where manager_id is not null
on conflict (recruiter_id, manager_id) do nothing;


