-- --- jobs-apply-url-backfill.sql ------------------------------------------

-- HireOrbit AI — backfill empty apply_url values to a Google-for-jobs
-- search so the "Apply on company site" button never opens an empty tab.
-- Existing rows where apply_url is null/empty get a query built from title +
-- company_name. New ingests already use the same fallback in code.
--
-- Idempotent: safe to re-run.

update public.jobs
   set apply_url = 'https://www.google.com/search?ibp=htl;jobs&q='
     || replace(replace(coalesce(title, '') || ' ' || coalesce(company_name, ''), ' ', '+'), '&', '%26')
 where apply_url is null
    or btrim(apply_url) = '';


-- --- jobs-publisher.sql ---------------------------------------------------

-- HireOrbit AI — record the publishing board (LinkedIn, Dice, Monster,
-- CareerBuilder, Indeed, Glassdoor, ZipRecruiter, …) for each job. Aggregators
-- like JSearch surface `job_publisher` on every result; we store it so the UI
-- can show & filter by the user-facing brand name even though all of those
-- listings technically came in through one driver.
--
-- Idempotent: safe to re-run.

alter table public.jobs
  add column if not exists publisher text;

create index if not exists jobs_publisher_idx
  on public.jobs (publisher);


-- --- jobs-unique-fix.sql --------------------------------------------------

-- HireOrbit AI — fix the (source, external_id) dedupe index.
-- The original index used a WHERE clause (partial unique index). PostgREST's
-- onConflict=source,external_id doesn't pass that WHERE through, so Postgres
-- can't match it and upserts fail with:
--   "there is no unique or exclusion constraint matching the ON CONFLICT specification"
--
-- The fix: drop the partial variant and create a plain unique index. NULLs
-- in Postgres unique indexes are distinct by default, so locally-created
-- jobs (source=NULL, external_id=NULL) still don't conflict with each other.
--
-- Idempotent: safe to re-run.

drop index if exists public.jobs_source_external_uniq;

create unique index if not exists jobs_source_external_uniq
  on public.jobs (source, external_id);

-- Also deactivate slugs we know to be dead (companies that removed their
-- public job feeds). They were causing 404 noise in the sync report.
update public.source_companies
   set is_active = false
 where (source = 'lever'      and slug in ('brex', 'mixpanel', 'netflix'))
    or (source = 'greenhouse' and slug in ('doordash'));


